import React, { useState, useEffect } from "react";
import axios from "axios";
import { getBaseURL } from "../apiConfig";
import "./AdminProductList.scss";

const ProductList = (props) => {
  const [products, setProducts] = useState([]);
  const [productName, setProductName] = useState("");
  const [productPrice, setProductPrice] = useState(0);
  const [productDesc, setProductDesc] = useState("");
  const [productStock, setProductStock] = useState(0);

  const addProduct = () => {
    if (props.isAdmin != 1) {
      alert("Access denied: Only admins can add products.");
      return;
    }

    let name = productName;
    let price = productPrice;
    let description = productDesc;
    let stock = productStock;

    if (name !== "" && price > 0 && description !== "" && stock >= 0) {
      axios
        .post(`${getBaseURL()}api/products/create`, { name, price, description, stock })
        .then(() => {
          console.log("Product added");
          fetchProducts();
        })
        .catch((err) => console.log("Error adding product", err));
    }
  };

  const openProductDetails = (product) => {
    if (props.isAdmin == 1) {
      props.handleProductDetails(product);
    } else {
      alert("Access denied: Only admins can view product details.");
    }
  };

  const deleteProduct = (productId) => {
    if (props.isAdmin != 1) {
      alert("Access denied: Only admins can delete products.");
      return;
    }

    axios
      .delete(`${getBaseURL()}api/products/delete/${productId}`)
      .then(() => {
        console.log("Deletion successful");
        fetchProducts();
      })
      .catch((err) => console.log("Error deleting product", err));
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  return (
    <div className="product-list-container">
      {props.isAdmin == 1 && ( // Restriction de l'ajout de produits
        <div className="add-product-section">
          <label htmlFor="productName">Product Name:</label>
          <input
            type="text"
            id="productName"
            value={productName}
            onChange={(e) => setProductName(e.target.value)}
            placeholder="Product Name"
          />

          <label htmlFor="productPrice">Price:</label>
          <input
            type="number"
            id="productPrice"
            value={productPrice}
            onChange={(e) => setProductPrice(e.target.value)}
            placeholder="Price"
          />

          <label htmlFor="productDesc">Description:</label>
          <input
            type="text"
            id="productDesc"
            value={productDesc}
            onChange={(e) => setProductDesc(e.target.value)}
            placeholder="Description"
          />

          <label htmlFor="productStock">Stock:</label>
          <input
            type="number"
            id="productStock"
            value={productStock}
            onChange={(e) => setProductStock(e.target.value)}
            placeholder="Stock"
          />

          <button onClick={addProduct}>Add Product</button>
        </div>
      )}

      <div className="product-list">
        <h1>Product List</h1>
        <table>
          <thead>
            <tr>
              <th>Id</th>
              <th>Name</th>
              <th>Price</th>
              <th>Description</th>
              <th>Stock</th>
              <th>Created Date</th>
              <th>Details</th>
              <th>Delete</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product) => (
              <tr key={product.productId}>
                <td>{product.productId}</td>
                <td>{product.name}</td>
                <td>{product.price}</td>
                <td>{product.description}</td>
                <td>{product.stock}</td>
                <td>{product.createdDate}</td>
                <td>
                  <button onClick={() => openProductDetails(product)}>
                    Details
                  </button>
                </td>
                <td>
                  <button onClick={() => deleteProduct(product.productId)}>
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ProductList;
